def create_ordinary_profiles(apps, schema_editor):
    """Additive rehearsal: every existing account becomes an ordinary user.

    Owner authority stays derived from Instance.owner; roles are never inferred
    from is_staff, is_superuser or study grants.
    """
    User = apps.get_model('auth', 'User')
    AccountProfile = apps.get_model('core', 'AccountProfile')
    AccountProfile.objects.bulk_create(
        [AccountProfile(user_id=uid, role='user', must_change_password=False, auth_version=1, revision=0)
         for uid in User.objects.values_list('id', flat=True).order_by('id')],
        ignore_conflicts=True,
    )


